begin;
set local request.jwt.claims='{"aal":"aal2"}';
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000981','matching-owner@example.test'),('00000000-0000-4000-8000-000000000982','matching-accounting@example.test');
update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000000981';update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000982';
insert into public.customers(id,legal_name,city,external_code) values('00000000-0000-4000-8000-000000000983','Negozio Aurora S.r.l.','MILANO','SYN-983'),('00000000-0000-4000-8000-000000000984','Negozio Aurora Shop','Milano','SYN-984'),('00000000-0000-4000-8000-000000000985','Negozio Aurora Srl','Roma','SYN-985');
insert into public.brands(id,name) values('00000000-0000-4000-8000-000000000986','Brànd Sintetico');
insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000000987','00000000-0000-4000-8000-000000000986','SS27','SS27');
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000981';
select public.start_import_batch('00000000-0000-4000-8000-000000000980','mixed','matching.csv',repeat('f',64),100);
insert into storage.objects(bucket_id,name,metadata) values('imports','00000000-0000-4000-8000-000000000980.csv','{"size":100}');
select public.configure_import_batch('00000000-0000-4000-8000-000000000980','{"revision":"00000000-0000-4000-8000-000000000988","profiles":[{"entity":"customers","sheet_name":"Negozi","header_row":1,"mapping":{},"options":{}},{"entity":"orders","sheet_name":"Ordini","header_row":1,"mapping":{},"options":{"allowCreateSeasons":true}}]}','{}',null);
select public.stage_import_rows('00000000-0000-4000-8000-000000000980','[{"entity":"customers","sheet":"Negozi","row_number":2,"raw":{},"mapped":{"legal_name":"NEGOZIO AURORA srl","city":"Milano"},"status":"valid"},{"entity":"customers","sheet":"Negozi","row_number":3,"raw":{},"mapped":{"legal_name":"Negozio nuovo","external_code":"NEW"},"status":"valid"},{"entity":"orders","sheet":"Ordini","row_number":2,"raw":{},"mapped":{"customer":"NEW","brand":"Brand sintetico","season":"SS27","sku":"SKU"},"status":"valid"},{"entity":"orders","sheet":"Ordini","row_number":3,"raw":{},"mapped":{"customer":"SYN-983","brand":"Brand sintetico","season":"SS27","sku":"SKU"},"status":"error","messages":[{"field":"order_date","code":"required"}]}]','00000000-0000-4000-8000-000000000988');
select is(app.import_key('Auróra S.r.l.'),app.import_key('AURORA srl'),'normalized accents, case and punctuation');
select is((select count(*) from jsonb_array_elements(public.import_matching('00000000-0000-4000-8000-000000000980')->'items') i where i->>'kind'='customer'),3::bigint,'customer subjects include pending store reference');
select is((select jsonb_array_length(i->'candidates') from jsonb_array_elements(public.import_matching('00000000-0000-4000-8000-000000000980')->'items') i where i->>'kind'='customer' and i->'subject'->>2='NEGOZIO AURORA srl'),2,'similar names suggested, different city excluded');
select is((select i->'candidates'->0->>'id' from jsonb_array_elements(public.import_matching('00000000-0000-4000-8000-000000000980')->'items') i where i->>'kind'='customer' and i->'subject'->>2='NEGOZIO AURORA srl'),'00000000-0000-4000-8000-000000000983','exact normalized name ranked first');
select is((select i->'candidates'->0->>'type' from jsonb_array_elements(public.import_matching('00000000-0000-4000-8000-000000000980')->'items') i where i->>'kind'='customer' and i->'subject'->>0='NEW' and i->'subject'->>2=''),'row','new customer referenced through staged row');
select lives_ok($$select public.resolve_import_match('00000000-0000-4000-8000-000000000980','customer','["","","NEGOZIO AURORA srl","Milano",""]','{"action":"link","type":"existing","id":"00000000-0000-4000-8000-000000000983"}','00000000-0000-4000-8000-000000000988')$$,'save existing link');
select is((select i->'choice'->>'id' from jsonb_array_elements(public.import_matching('00000000-0000-4000-8000-000000000980')->'items') i where i->>'kind'='customer' and i->'subject'->>2='NEGOZIO AURORA srl'),'00000000-0000-4000-8000-000000000983','choice persists after reload');
select throws_ok($$select public.resolve_import_match('00000000-0000-4000-8000-000000000980','customer','["NEW","","","",""]','{"action":"create"}','00000000-0000-4000-8000-000000000988')$$,'42501','FORBIDDEN','order reference cannot create an invented customer');
select throws_ok($$select public.resolve_import_match('00000000-0000-4000-8000-000000000980','customer','["NEW","","Negozio nuovo","",""]','{"action":"create"}',null)$$,'40001','CONFIG_CONFLICT','revision is required for decisions');
select throws_ok($$select public.resolve_import_match('00000000-0000-4000-8000-000000000980','brand','["Brand sintetico"]','{"action":"link","type":"existing","id":"00000000-0000-4000-8000-000000000983"}','00000000-0000-4000-8000-000000000988')$$,'23514','INVALID_TARGET','cannot cross target entity');
select lives_ok($$select public.exclude_import_errors('00000000-0000-4000-8000-000000000980',array(select id from public.import_rows where batch_id='00000000-0000-4000-8000-000000000980' and status='error'),'00000000-0000-4000-8000-000000000988')$$,'explicitly exclude listed error rows');
select is((select count(*) from public.import_rows where batch_id='00000000-0000-4000-8000-000000000980' and status='error'),0::bigint,'excluded error no longer active');
select throws_ok($$select public.import_matching('00000000-0000-4000-8000-000000000980',0)$$,'23514','INVALID_FILTERS','page bounds');
select throws_ok($$select public.import_matching('00000000-0000-4000-8000-000000000980',1,null)$$,'23514','INVALID_FILTERS','threshold cannot be null');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000982';
select throws_ok($$select public.import_matching('00000000-0000-4000-8000-000000000980')$$,'42501','FORBIDDEN','accounting cannot inspect mixed import');
select * from finish();rollback;
